-- 字段级授权与权限变更通知。
BEGIN;

CREATE TABLE IF NOT EXISTS "字段授权规则" (
    "编号" bigint GENERATED BY DEFAULT AS IDENTITY,
    "角色编号" integer NOT NULL,
    "资源" varchar(100) NOT NULL,
    "字段" varchar(100) NOT NULL,
    "是否可读" boolean NOT NULL DEFAULT FALSE,
    "是否可写" boolean NOT NULL DEFAULT FALSE,
    "建立人编号" integer,
    "更新时间" timestamp without time zone NOT NULL DEFAULT CURRENT_TIMESTAMP,
    CONSTRAINT "pk_字段授权规则" PRIMARY KEY ("编号"),
    CONSTRAINT "fk_字段授权规则_角色" FOREIGN KEY ("角色编号") REFERENCES "角色"("编号"),
    CONSTRAINT "uq_字段授权规则_角色资源字段" UNIQUE ("角色编号", "资源", "字段")
);

CREATE TABLE IF NOT EXISTS "权限变更通知" (
    "编号" bigint GENERATED BY DEFAULT AS IDENTITY,
    "接收人编号" integer NOT NULL,
    "角色编号" integer,
    "资源" varchar(100) NOT NULL,
    "字段" varchar(100) NOT NULL,
    "变更类型" varchar(20) NOT NULL,
    "是否可读" boolean NOT NULL,
    "是否可写" boolean NOT NULL,
    "操作人编号" integer,
    "是否已读" boolean NOT NULL DEFAULT FALSE,
    "建立时间" timestamp without time zone NOT NULL DEFAULT CURRENT_TIMESTAMP,
    CONSTRAINT "pk_权限变更通知" PRIMARY KEY ("编号"),
    CONSTRAINT "fk_权限变更通知_接收人" FOREIGN KEY ("接收人编号") REFERENCES "人员"("编号")
);

CREATE INDEX IF NOT EXISTS "ix_权限变更通知_接收人状态"
    ON "权限变更通知" ("接收人编号", "是否已读", "建立时间" DESC);

UPDATE "系统迁移版本"
   SET "版本" = 62,
       "脚本" = '001-062',
       "检查摘要" = '增加字段级授权规则、敏感字段脱敏和权限变更通知'
 WHERE "编号" = 1;

COMMIT;
